/**
 * @summary Get availability participation and reminder status for a league week
 */
export const getGetAvailabilityParticipationUrl = (
  leagueId: number,
  weekOf: string,
) => {
  return `/api/availability/participation/${leagueId}/${weekOf}`;
};

export const getAvailabilityParticipation = async (
  leagueId: number,
  weekOf: string,
  options?: RequestInit,
): Promise<AvailabilityParticipationResponse> => {
  return customFetch<AvailabilityParticipationResponse>(
    getGetAvailabilityParticipationUrl(leagueId, weekOf),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetAvailabilityParticipationQueryKey = (
  leagueId: number,
  weekOf: string,
) => {
  return [`/api/availability/participation/${leagueId}/${weekOf}`] as const;
};

